package io.github.diodeme.ji.credential.sqlite;

import io.github.diodeme.ji.storage.sqlite.SqliteMigration;
import io.github.diodeme.ji.storage.sqlite.SqliteMigrationManager;
import io.github.diodeme.ji.storage.sqlite.SqliteSchema;
import java.nio.file.Path;
import java.util.List;
import java.util.Set;

/** Forward-only catalog for encrypted Provider credentials. */
final class CredentialDatabaseMigrations {
    private static final Set<String> COLUMNS = Set.of(
            "credential_id", "revision", "key_id", "nonce", "ciphertext", "auth_tag", "updated_at");

    private CredentialDatabaseMigrations() {}

    static void migrate(Path database) {
        new SqliteMigrationManager(database, "credential", List.of(new SqliteMigration(1, "encrypted-credentials", List.of(
                """
                CREATE TABLE IF NOT EXISTS provider_credentials (
                  credential_id TEXT PRIMARY KEY,
                  revision INTEGER NOT NULL CHECK (revision > 0),
                  key_id TEXT NOT NULL,
                  nonce BLOB NOT NULL CHECK (length(nonce) = 12),
                  ciphertext BLOB NOT NULL,
                  auth_tag BLOB NOT NULL CHECK (length(auth_tag) = 16),
                  updated_at TEXT NOT NULL
                ) STRICT
                """))), connection -> {
            var schema = SqliteSchema.tables(connection);
            if (schema.isEmpty()) return 0;
            return schema.keySet().equals(Set.of("provider_credentials"))
                    && schema.get("provider_credentials").equals(COLUMNS) ? 1 : -1;
        }).migrate();
    }
}
